"""Public storefront adapters for selected Zhytomyr stores; prices are never generated by LLM."""
from __future__ import annotations
from pathlib import Path
import requests,re,json,time,threading,math,hashlib
from urllib.parse import urljoin,urlparse
from concurrent.futures import ThreadPoolExecutor
from bs4 import BeautifulSoup
from core import norm,stamp,AppError

ROOT=Path(__file__).resolve().parent.parent
CACHE=ROOT/'.runtime'/'prices';CACHE.mkdir(parents=True,exist_ok=True)
ATB_LOCK=threading.Lock();SILPO_LIMIT=threading.Semaphore(2)
ATB_SESSION=None
STORES={
 'atb':{'name':'АТБ','city':'Житомир','address':'вул. Велика Бердичівська, 70б',
  'store_id':'578','internal_shop_id':'100780','city_id':'497','website':'https://www.atbmarket.com'},
 'silpo':{'name':'Сільпо','city':'Житомир','address':'вул. Грушевського Михайла, 5',
  'store_id':'1edb7340-abf6-6352-b3df-73524574f50b','external_id':'2938','website':'https://silpo.ua'}}

def context():return STORES

def package_amount(text):
 matches=list(re.finditer(r'(?<![\d.])(\d+(?:[.,]\d+)?)\s*(кг|мл|шт\.?|г|л)(?![а-яіїєґa-z])',str(text).casefold()))
 if not matches:return None,None
 m=matches[-1];quantity=float(m.group(1).replace(',','.'));unit=m.group(2).rstrip('.')
 if unit=='кг':quantity*=1000;unit='г'
 elif unit=='л':quantity*=1000;unit='мл'
 return quantity,unit

def product(store,name,price,url,weighted=False,basis='',pack='',available=True,step=1,stock=None):
 price=float(price)
 if not math.isfinite(price) or price<=0:raise ValueError('Invalid catalog price')
 qty,unit=package_amount(name)
 if not qty:qty,unit=package_amount(pack)
 if weighted:
  if 'кг' in str(basis):qty,unit=1000,'г';basis='кг'
  elif str(basis).strip('/')=='г':qty,unit=1,'г';basis='г'
 else:basis='уп.'
 return {'id':hashlib.sha256(url.encode()).hexdigest()[:12],'store':store,'name':name,'price':price,
  'url':url,'weighted':bool(weighted),'price_unit':basis or 'уп.','package_quantity':qty,
  'package_unit':unit,'package_label':pack or (f'{qty:g} {unit}' if qty else ''),
  'available':bool(available),'step':float(step or 1),'stock':stock,'source':'live',
  'fetched_at':stamp(),'city':'Житомир','address':STORES[store]['address']}

def atb_session():
 global ATB_SESSION
 if ATB_SESSION is not None:return ATB_SESSION
 s=requests.Session()
 home=s.get('https://www.atbmarket.com/',timeout=(8,25));home.raise_for_status()
 csrf=BeautifulSoup(home.text,'html.parser').select_one('meta[name="csrf-token"]')
 if not csrf:raise ValueError('Магазин змінив структуру вибору адреси.')
 r=s.post('https://www.atbmarket.com/site/setdelivery',data={'delivery':0,'user_store':578,'cityid':497,'pathname':'/sch'},
  headers={'X-Requested-With':'XMLHttpRequest','X-CSRF-Token':csrf['content']},timeout=(8,25))
 r.raise_for_status()
 if r.json().get('res')!='ok':raise ValueError('Не вдалося обрати магазин АТБ у Житомирі.')
 ATB_SESSION=s
 return s

def atb_search(query):
 global ATB_SESSION
 with ATB_LOCK:
  s=atb_session()
  r=s.get('https://www.atbmarket.com/sch',params={'query':query},timeout=(8,25));r.raise_for_status()
  soup=BeautifulSoup(r.text,'html.parser')
  # Do not attribute another storefront's prices to the chosen Zhytomyr store.
  ids={str(x.get('data-shopid')) for x in soup.select('[data-shopid]')}
  if ids and STORES['atb']['internal_shop_id'] not in ids:
   ATB_SESSION=None;raise ValueError('Каталог АТБ повернув інший магазин; ціни не використані.')
  found=[]
  for article in soup.select('article.catalog-item'):
   title=article.select_one('.catalog-item__title a')
   price=article.select_one('.catalog-item__product-price.product-price--weight data.product-price__top[value]')
   if not title or not price:continue
   counter=article.select_one('[data-current-measure]')
   weighted=bool(counter and counter.get('data-current-measure')=='weight')
   unit=price.select_one('.product-price__unit')
   try:
    found.append(product('atb',title.get_text(' ',strip=True),price['value'],urljoin(STORES['atb']['website'],title['href']),
     weighted,unit.get_text(strip=True).strip('/') if unit else '',
     available=not bool(article.select_one('.catalog-item__not-available-btn')),
     step=float(counter.get('data-step','1')) if counter else 1))
   except (ValueError,TypeError):continue
  return found

def silpo_search(query):
 with SILPO_LIMIT:
  r=requests.get(f"https://sf-ecom-api.silpo.ua/v1/uk/branches/{STORES['silpo']['store_id']}/products",
   params={'search':query,'limit':60,'offset':0},timeout=(8,25));r.raise_for_status()
  data=r.json()
  if not isinstance(data.get('items'),list):raise ValueError('Магазин змінив формат каталогу.')
  found=[]
  for item in data['items']:
   try:
    found.append(product('silpo',item['title'],item['price'],'https://silpo.ua/product/'+item['slug'],
      item.get('weighted',False),item.get('ratio',''),item.get('displayRatio',''),
      available=float(item.get('stock',0))>0,step=item.get('addToBasketStep',1),stock=item.get('stock')))
   except (ValueError,KeyError,TypeError):continue
  return found

STOP={'для','без','та','або','і','з','зі','на','за','до','від','вищого','вищий','гатунок','смаком','середня','велика'}
ALIASES={'ребра':'реб','реберця':'реб','ребер':'реб','свинячі':'свин','свинячий':'свин','свинячих':'свин',
 'свиняче':'свин','свиняча':'свин','куряче':'кур','куряча':'кур','курячий':'кур','куряче':'кур',
 'стегно':'стег','яйця':'яйц','яйце':'яйц','печериці':'печер','печериць':'печер','часнику':'часник',
 'дріжджі':'дріждж','дріжджів':'дріждж','сухі':'сух','сухих':'сух','моцарела':'моцарел','моцарели':'моцарел',
 'лавровий':'лавр','лаврове':'лавр','чорний':'чорн','горошок':'горош','горошком':'горош','духмяний':'духм',
 'соняшникова':'соняшник','соняшникової':'соняшник','оливкова':'оливк','оливкової':'оливк'}

def tokens(text):
 words=re.findall(r'[а-яіїєґa-z]+',norm(text))
 return [ALIASES.get(w,w[:max(4,len(w)-2)] if len(w)>5 else w) for w in words if len(w)>1 and w not in STOP]

def match_score(query,name):
 matching_query=re.sub(r'без кістки(?: та шкіри)?','',norm(query))
 q=tokens(matching_query);n=tokens(name)
 families=[('паприк',r'^(паприка|перець|спеції|приправа|суміш)'),('томатний соус',r'^(соус|кетчуп)'),('італійськ',r'^(трава|трави|суміш|спеції|приправа)'),('олія',r'^олія')]
 for key,pattern in families:
  if key in norm(query) and not re.search(pattern,norm(name)):return 0
 if not q:return 0
 hits=[any(t.startswith(k) or k.startswith(t) for t in n) for k in q]
 score=sum(hits)/len(hits)
 # No products matching only a secondary adjective or ingredients of ready-made meals.
 main=q[0]
 if not any(t.startswith(main) or main.startswith(t) for t in n):return 0
 if score<0.65:return 0
 head=re.split(r'\s(?:з|зі|із|у|в)\s',norm(name),maxsplit=1)[0]
 if not any(t.startswith(main) or main.startswith(t) for t in tokens(head)):return 0
 if any(w in norm(query) for w in ['печер','капуст','картоп','моркв','буряк','цибул','часник','кріп']):
  for w in ['маринован','консервован','сушен','квашен','солон','заморож']:
   if w in norm(name) and w not in norm(query):return 0
 if 'олія' in norm(query) and 'суміш' in norm(name) and 'суміш' not in norm(query):return 0
 if 'без кістки' in norm(query) and not any(w in norm(name) for w in ['без кіст','філе']):return 0
 excluded=['борщ','салат','піца','пельмен','вареник','чипс','суп ','соус','кетчуп','маринад','чіабат','пиріг','пиріж','сік ','напій','корм','цукерк','сухар']
 if any(x in norm(name) and x not in norm(query) for x in excluded):return 0
 for term in ['копчен','оливк','соняшник','моцарел','мелени','горош','сух','пшенич','духм']:
  if term in norm(query) and term not in norm(name):return 0
 # Prefer names beginning with the ingredient and concise plain ingredients.
 score+=0.2 if n and (n[0].startswith(main) or main.startswith(n[0])) else 0
 score-=min(0.18,max(0,len(n)-5)*0.015)
 return round(score,3)

def catalog_query(query):
 query=query.split(' для ',1)[0]
 s=norm(query)
 if 'моцар' in s:return 'моцарела'
 if 'борош' in s:return 'борошно'
 if 'дріждж' in s:return 'дріжджі'
 if 'перець' in s:return 'перець духмяний' if 'духм' in s else ('перець чорний горошок' if 'горош' in s else 'перець')
 if 'стег' in s and ('кур' in s):return 'філе стегна' if 'без кіст' in s else 'стегно'
 if 'реб' in s and 'свин' in s:return 'ребра'
 if 'паприк' in s:return 'паприка'
 if 'олія' in s:
  return 'олія соняшникова' if 'соняш' in s else ('олія оливкова' if 'оливк' in s else 'олія')
 return query.split(' для ',1)[0]

def search(store,query,refresh=False,match_name=None):
 query=str(query).strip()[:100]
 if not query:raise AppError('Порожній пошуковий запит.')
 key=hashlib.sha256(('v4'+store+STORES[store]['store_id']+norm(query)+norm(match_name or query)).encode()).hexdigest()
 path=CACHE/(key+'.json');cached=None
 try:
  if path.exists():cached=json.loads(path.read_text(encoding='utf-8'))
 except (OSError,ValueError):pass
 if cached and not refresh and time.time()-cached['epoch']<1800:
  return {**cached['result'],'cache':True,'cache_age_seconds':round(time.time()-cached['epoch'])}
 try:
  retrieval=catalog_query(query)
  raw=atb_search(retrieval) if store=='atb' else silpo_search(retrieval)
  ranked=[];matched_out_of_stock=0
  for p in raw:
   p['match_score']=match_score(match_name or query,p['name'])
   if p['match_score']>0:
    if p['available']:ranked.append(p)
    else:matched_out_of_stock+=1
  ranked.sort(key=lambda p:(-p['match_score'],p['price']/(p['package_quantity'] or 1)))
  result={'store':store,'query':query,'products':ranked[:8],'fetched_at':stamp(),
   'status':'ok' if ranked else ('out_of_stock' if matched_out_of_stock else 'not_found'),'cache':False,'raw_count':len(raw),
   'message':'' if ranked else ('Немає в наявності: відповідні товари є в каталозі, але доступного залишку немає.' if matched_out_of_stock else 'Не знайдено відповідного товару. Це не нульова ціна; рядок не включено до кошторису.')}
  path.write_text(json.dumps({'epoch':time.time(),'result':result},ensure_ascii=False),encoding='utf-8')
  return result
 except (requests.RequestException,ValueError,KeyError,TypeError) as exc:
  message='Каталог тимчасово недоступний або змінив формат. Ціну не вигадуємо.'
  if cached:
   result={**cached['result'],'cache':True,'stale':True,'status':'stale','message':message+' Показано старі дані з позначеним часом.'}
   for p in result['products']:p['source']='stale_cache'
   return result
  return {'store':store,'query':query,'products':[],'status':'unavailable','cache':False,'message':message,'error_type':type(exc).__name__}

def estimate(ingredient,p):
 original=ingredient;draft=ingredient.get('budget_estimate')
 if draft and (ingredient.get('unknown_quantity') or ingredient.get('quantity_max') is None or ingredient.get('unit')!=p.get('package_unit')):
  ingredient={**ingredient,**draft,'unknown_quantity':False};ingredient['is_budget_draft']=True
 q=ingredient.get('quantity_max');lo=ingredient.get('quantity_min')
 unit=ingredient.get('unit','');capacity=p.get('package_quantity');punit=p.get('package_unit')
 result={'purchase_cost':None,'recipe_cost_min':None,'recipe_cost_max':None,'purchase_quantity':None,'note':'','approximate':bool(ingredient.get('is_budget_draft') or ingredient.get('is_estimate'))}
 pantry=any(w in norm(original.get('name','')) for w in ['сіль','перець','лавр','паприк','трав','олія','кетчуп','соус','цукор'])
 if not p['weighted'] and pantry and (q is None or ingredient.get('unknown_quantity') or unit!=punit):
  return {**result,'purchase_cost':p['price'],'purchase_quantity':1,'purchase_label':'1 уп. попередньо','approximate':True,'note':'Для орієнтовної покупки закладено одну упаковку. Залишок удома можна виключити.'}
 if q is None or ingredient.get('unknown_quantity'):
  result['note']='Кількість не повністю задана — вартість покупки не визначена.';return result
 q=float(q);lo=float(lo or q)
 if not capacity or unit!=punit:
  result['note']='Потрібно узгодити одиниці рецепта й фасування товару.';return result
 if p['weighted']:
  kg=q/capacity;step=float(p.get('step',.1));buy=math.ceil((kg-1e-10)/step)*step
  if p.get('stock') is not None and buy>float(p['stock']):
   result['note']='Наявної кількості товару недостатньо.';return result
  result['purchase_quantity']=round(buy,3);result['purchase_label']=f'{buy:g} {p["price_unit"]}'
  result['purchase_cost']=round(buy*p['price'],2)
 else:
  count=math.ceil((q-1e-10)/capacity)
  if p.get('stock') is not None and count>float(p['stock']):
   result['note']='Наявної кількості упаковок недостатньо.';return result
  result['purchase_quantity']=count;result['purchase_label']=f'{count} уп.'
  result['purchase_cost']=round(count*p['price'],2)
 result['recipe_cost_min']=round(lo/capacity*p['price'],2)
 result['recipe_cost_max']=round(q/capacity*p['price'],2)
 if lo!=q:result['note']='Покупка розрахована за верхньою межею діапазону.'
 if ingredient.get('needs_review'):result['note']+=' Перевірте позначену кількість або альтернативу.'
 return result

def compare(ingredients,refresh=False):
 jobs=[]
 with ThreadPoolExecutor(max_workers=4) as pool:
  for ing in ingredients:
   if ing.get('excluded'):continue
   for store in STORES:jobs.append((ing,store,pool.submit(search,store,ing.get('query') or ing.get('name'),refresh,ing.get('name'))))
  rows={}
  for ing,store,future in jobs:
   found=future.result()
   for p in found['products']:p['estimate']=estimate(ing,p)
   if found['products']:
    best=max(p['match_score'] for p in found['products'])
    found['products'].sort(key=lambda p:(-round(min(p['match_score'],1.0),1),p['estimate']['purchase_cost'] is None,p['estimate']['purchase_cost'] if p['estimate']['purchase_cost'] is not None else p['price']/(p['package_quantity'] or 1)))
   rows.setdefault(ing['id'],{})[store]=found
 return {'items':rows,'context':STORES,'fetched_at':stamp()}

